\begin{lem}
\label{X-has-Gamma-action}
\uses{X-inf-is-proj-lim,conjugate-action}
Each $X_n$ has a natural $\Gamma_n$-action, and is a $\BZ_p[\Gamma_n]$-module.
$X_\infty$ has a natural $\Gamma$-action, and is a $\Lambda$-module.
\end{lem}

